  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-text);
  line-height: 1.2;
  margin-bottom: .75rem;
}

.page-header .subtitle {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  max-width: 480px;
  margin: 0 auto;
