 * Cat FAQ – Disclosure Widget
 *
 * React-inspired component pattern:
 *   FaqItem(data)  → builds one question/answer card
 *   FaqList(items) → renders all cards into the DOM
 */

const FAQ_DATA = [
  {
    id: "faq-1",
    question: "How often should I feed my cat?",
    answer:
      "Most adult cats thrive on <strong>two meals per day</strong>, roughly 12 hours apart. " +
      "Kittens under six months need three to four smaller meals. " +
      "Always follow the portion guidance on your cat's food label and adjust for activity level — " +
      "indoor cats tend to burn fewer calories than outdoor ones.",
  },
  {
    id: "faq-2",
    question: "Why does my cat knead?",
    answer:
      "Kneading — also called "making biscuits" — is a <strong>comforting, instinctive behaviour</strong> " +
      "kittens develop while nursing. Adult cats retain it as a sign of contentment or affection. " +
      "If your cat kneads on you, consider it a high compliment; they're telling you they feel safe and happy.",
  },
  {
    id: "faq-3",
    question: "Do cats always land on their feet?",
    answer:
      "Cats have a remarkable <strong>righting reflex</strong> that lets them orient their body mid-fall, " +
      "but they don't always land safely. Short falls can actually be more dangerous because there isn't " +
      "enough time to fully rotate. Always keep windows screened and balconies secured to prevent falls.",
  },
  {
    id: "faq-4",
    question: "How much sleep does a cat need?",
    answer:
      "Cats are <strong>polyphasic sleepers</strong> and typically snooze 12–16 hours per day — " +
      "some senior cats sleep up to 20 hours. This conserves energy between bursts of hunting activity. " +
      "As long as your cat is alert and playful when awake, all that napping is perfectly normal.",
  },
  {
    id: "faq-5",
    question: "Why does my cat bring me dead animals?",
    answer:
      "Your cat views you as a <strong>beloved, if somewhat incompetent, family member</strong> who needs hunting lessons. " +
      "Cats in the wild bring prey back to their group, and your cat is doing exactly that — teaching you to hunt. " +
      "The best response is a calm thank-you and a swift disposal while your cat isn't watching.",
  },
  {
    id: "faq-6",
    question: "Are cats truly solitary animals?",
    answer:
      "Wild cats are largely solitary hunters, but domestic cats have adapted to be far more <strong>social and flexible</strong>. " +
      "Many cats enjoy the company of other cats or humans, especially when socialised young. " +
      "That said, each cat has its own personality — some genuinely prefer solo living, and that's okay too.",
  },
  {
    id: "faq-7",
    question: "How do I know if my cat is sick?",
    answer:
      "Key warning signs include: <strong>changes in appetite or water intake</strong>, lethargy, hiding more than usual, " +
      "vomiting or diarrhoea lasting more than 24 hours, laboured breathing, weight loss, or changes in litter-box habits. " +
      "Cats instinctively mask illness, so any noticeable behaviour change warrants a call to your vet.",
  },
  {
    id: "faq-8",
    question: "Why do cats purr?",
    answer:
      "Purring is produced by rapid laryngeal muscle contractions that dilate and constrict the glottis during breathing. " +
      "Cats purr when <strong>content, but also when stressed or in pain</strong> — it may be a self-soothing mechanism. " +
      "Interestingly, the frequency range of a cat's purr (25–150 Hz) overlaps with frequencies used in therapeutic " +
      "vibration to promote bone healing and reduce pain.",
  },
];

/* ── Component: chevron SVG icon ─────────────────────── */
function ChevronIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 16 16");
  svg.setAttribute("width", "14");
  svg.setAttribute("height", "14");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", "2.2");
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");

  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
  path.setAttribute("points", "3 5 8 11 13 5");
  svg.appendChild(path);
  return svg;
}

/* ── Component: single FAQ card ──────────────────────── */
function FaqItem({ id, question, answer }) {
  const panelId = `${id}-panel`;

  // Wrapper card
  const card = document.createElement("div");
  card.className = "example";

  // Heading + button
  const heading = document.createElement("h2");

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "disclosure-btn";
  btn.setAttribute("aria-expanded", "false");
  btn.setAttribute("aria-controls", panelId);

  const questionText = document.createElement("span");
  questionText.textContent = question;

  const iconWrap = document.createElement("span");
  iconWrap.className = "icon";
  iconWrap.setAttribute("aria-hidden", "true");
  iconWrap.appendChild(ChevronIcon());

  btn.appendChild(questionText);
  btn.appendChild(iconWrap);
  heading.appendChild(btn);

  // Answer panel
  const panel = document.createElement("div");
  panel.className = "details";
  panel.id = panelId;
  panel.setAttribute("aria-hidden", "true");
  panel.setAttribute("role", "region");
  panel.setAttribute("aria-labelledby", `${id}-btn`);
  btn.id = `${id}-btn`;

  const body = document.createElement("div");
  body.className = "answer-body";
  body.innerHTML = answer;

  panel.appendChild(body);
  card.appendChild(heading);
  card.appendChild(panel);

  // Toggle behaviour
  btn.addEventListener("click", () => {
    const isExpanded = btn.getAttribute("aria-expanded") === "true";
    btn.setAttribute("aria-expanded", String(!isExpanded));
    panel.setAttribute("aria-hidden", String(isExpanded));
  });

  // Keyboard: Escape collapses
  btn.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && btn.getAttribute("aria-expanded") === "true") {
      btn.setAttribute("aria-expanded", "false");
      panel.setAttribute("aria-hidden", "true");
    }
  });

  return card;
}

/* ── Component: FAQ list ──────────────────────────────── */
function FaqList(items) {
  const list = document.createElement("div");
  list.className = "faq-list";
  list.setAttribute("role", "list");

  items.forEach((item) => {
    const li = document.createElement("div");
    li.setAttribute("role", "listitem");
    li.appendChild(FaqItem(item));
    list.appendChild(li);
  });

  return list;
}

/* ── Mount ────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", () => {
  const root = document.getElementById("faq-root");
  if (root) root.appendChild(FaqList(FAQ_DATA));
});
