  --transition:        220ms ease;
  --font-sans: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  padding: 0 1rem 4rem;
}

/* ── Skip link ────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: 0 0 6px 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 0; }

/* ── Page layout ──────────────────────────────────────── */
.page-header {
  max-width: 680px;
  margin: 3rem auto 2.5rem;
  text-align: center;
}

.page-header .eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: var(--color-accent-bg);
  border: 1px solid #f0d5b0;
  border-radius: 999px;
  padding: .25rem .85rem;
  margin-bottom: 1rem;
}

.page-header h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-text);
  line-height: 1.2;
  margin-bottom: .75rem;
}

.page-header .subtitle {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  max-width: 480px;
  margin: 0 auto;
}

/* ── FAQ list ─────────────────────────────────────────── */
.faq-list {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

/* ── Each question/answer card ────────────────────────── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow var(--transition);
}

.example:has([aria-expanded="true"]) {
  border-color: #d4b896;
  box-shadow: 0 2px 6px rgba(0,0,0,.06), 0 8px 20px rgba(0,0,0,.07);
}

/* ── Disclosure trigger button ────────────────────────── */
.disclosure-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.4rem;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  border-radius: var(--radius-card);
  transition: background var(--transition);
}

.disclosure-btn:hover { background: #faf8f5; }

.disclosure-btn:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: -3px;
  border-radius: var(--radius-card);
}

/* Icon */
.disclosure-btn .icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--color-accent-bg);
  color: var(--color-accent);
  transition: background var(--transition), transform var(--transition);
}

.disclosure-btn[aria-expanded="true"] .icon {
  transform: rotate(180deg);
  background: #f0d5b0;
}

/* ── Answer panel ─────────────────────────────────────── */
.details {
  overflow: hidden;
  /* Animate height via max-height trick */
  max-height: 0;
  transition: max-height var(--transition), padding var(--transition);
}

.details[aria-hidden="false"] {
  max-height: 600px; /* large enough for any answer */
}

.details .answer-body {
  padding: 0 1.4rem 1.25rem;
  color: var(--color-text-muted);
  font-size: .96rem;
  line-height: 1.7;
  border-top: 1px solid var(--color-border);
  padding-top: 1rem;
}

.details .answer-body strong { color: var(--color-text); }

/* ── Footer ───────────────────────────────────────────── */
.page-footer {
  max-width: 680px;
  margin: 3rem auto 0;
  text-align: center;
  font-size: .85rem;
  color: var(--color-text-muted);
}

/* ── Reflow (320px) ───────────────────────────────────── */
@media (max-width: 360px) {
  .disclosure-btn { padding: .9rem 1rem; font-size: .95rem; }
  .details .answer-body { padding: .75rem 1rem 1rem; }
}

/* ── Forced colors ────────────────────────────────────── */
@media (forced-colors: active) {
  .disclosure-btn .icon { forced-color-adjust: auto; }
  .example:has([aria-expanded="true"]) { border-color: Highlight; }
  .disclosure-btn:focus-visible { outline-color: Highlight; }
}

/* ── Reduced motion ───────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .details,
  .disclosure-btn .icon,
  .disclosure-btn,
  .example { transition: none; }
}
